CREATE TABLE IF NOT EXISTS player_arrival_bonuses (
  player_id  INT UNSIGNED PRIMARY KEY,
  awarded_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (player_id) REFERENCES players(id) ON DELETE CASCADE
) ENGINE=InnoDB;

ALTER TABLE transactions
  MODIFY kind ENUM('depot','retrait','achat','salaire','virement_recu','virement_envoye','bonus_arrivee') NOT NULL;

UPDATE cities SET name = CONVERT(UNHEX('41646A616DC3A9') USING utf8mb4)
WHERE id = 6 AND name LIKE CONCAT('%', CONVERT(UNHEX('E2949C') USING utf8mb4), '%') COLLATE utf8mb4_unicode_ci;

UPDATE cities
SET description = CASE id
  WHEN 1 THEN CONVERT(UNHEX('') USING utf8mb4)
  WHEN 2 THEN CONVERT(UNHEX('517561727469657220706F70756C6169726520657420766976616E742C2063C3A96CC3A862726520706F757220736573206D61717569732C207361206D75736971756520657420736F6E20C3A96E65726769652E') USING utf8mb4)
  WHEN 3 THEN CONVERT(UNHEX('51756172746965722072C3A9736964656E7469656C2063686963203A2076696C6C61732C20616D62617373616465732C20756E69766572736974C3A9732065742072657374617572616E747320686175742064652067616D6D652E') USING utf8mb4)
  WHEN 4 THEN CONVERT(UNHEX('5A6F6E6520342C20636F6D6D657263657320657420656E747265707269736573203A206C652063C5937572206465732061666661697265732065742064657320627572656175782E') USING utf8mb4)
  WHEN 5 THEN CONVERT(UNHEX('43656E7472652061646D696E69737472617469662065742066696E616E636965722C20746F757273206574207369C3A8676573206465732062616E717565732E') USING utf8mb4)
  WHEN 6 THEN CONVERT(UNHEX('4772616E64206D61726368C3A92C20676172657320726F757469C3A872657320657420636F6D6D6572636520C3A02063686171756520636F696E206465207275652E') USING utf8mb4)
END
WHERE id IN (1, 2, 3, 4, 5, 6)
  AND (
    description LIKE CONCAT('%', CONVERT(UNHEX('E2949C') USING utf8mb4), '%') COLLATE utf8mb4_unicode_ci
    OR description LIKE CONCAT('%', CONVERT(UNHEX('E294BC') USING utf8mb4), '%') COLLATE utf8mb4_unicode_ci
  );
